// Format today's date for the page title
const today = new Date();
today.setHours(0, 0, 0, 0);
const dateStr = today.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Prepare Notion blocks for each event
const events = $input.all().map(item => item.json);
const blocks = [];

// Add title block
blocks.push({
  object: 'block',
  type: 'heading_1',
  heading_1: {
    rich_text: [{
      type: 'text',
      text: { content: `📅 ${dateStr}` }
    }]
  }
});

// Sort events by start time
events.sort((a, b) => new Date(a.start.dateTime || a.start.date) - new Date(b.start.dateTime || b.start.date));

// Add each event as a block
for (const event of events) {
  const start = new Date(event.start.dateTime || event.start.date);
  const end = new Date(event.end.dateTime || event.end.date);

  // Format time
  const timeStr = `${start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - ${end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;

  // Add event block
  blocks.push({
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [
        {
          type: 'text',
          text: { content: `${timeStr} | ${event.summary}` },
          annotations: { bold: true }
        }
      ]
    }
  });

  // Add description if available
  if (event.description) {
    blocks.push({
      object: 'block',
      type: 'bulleted_list_item',
      bulleted_list_item: {
        rich_text: [{
          type: 'text',
          text: { content: event.description.substring(0, 100) + (event.description.length > 100 ? '...' : '') }
        }]
      }
    });
  }
}

// If no events, add a note
if (events.length === 0) {
  blocks.push({
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [{
        type: 'text',
        text: { content: 'No events scheduled for today' }
      }]
    }
  });
}

return [{ json: {
  title: dateStr,
  blocks: blocks
} }];
